        // observation may retain its original typed baseline after bind.
        $columns = $mysql
            ? $pdo->query("SELECT column_name FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='familyhub_crypto_capture_sources_v3'")->fetchAll(\PDO::FETCH_COLUMN)
            : array_column($pdo->query('PRAGMA table_info(familyhub_crypto_capture_sources_v3)')->fetchAll(\PDO::FETCH_ASSOC),'name');
