        if(!$exists){$pdo->exec('CREATE INDEX familyhub_crypto_record_cursor ON familyhub_crypto_records(scope_id,sequence)');}
        $indexes=[
            ['familyhub_crypto_scheduling_uses_v2','familyhub_crypto_schedule_target','scope_id,target_id,use_token'],
