            ['familyhub_crypto_blobs_v2','familyhub_crypto_blob_owner','owner_account_id,complete'],
        ];
        foreach ($indexes as [$table,$name,$columns]) {
            $query=$pdo->prepare($mysql?'SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND INDEX_NAME=?':"SELECT COUNT(*) FROM sqlite_master WHERE type='index' AND name=?");
            $query->execute($mysql?[$table,$name]:[$name]);$found=(int)$query->fetchColumn();$query->closeCursor();
            if (!$found) { $pdo->exec('CREATE INDEX '.$name.' ON '.$table.'('.$columns.')'); }
        }
